entries[106371] = { ["name"] = "Stunde des Zwielichts", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nDie Stunde des Zwielichts bricht über Ultraxions Gegner herein. Gegner, die sich im Zwielichtreich befinden, erleiden 14433 Schattenschaden, dem nicht widerstanden werden kann. Gegner in der normalen Welt werden sofort zurück ins Zwielichtreich gezogen. Wenn keine Gegner von 'Stunde des Zwielichts' getroffen werden, erleiden die Aspekte den Gesamtschaden des Angriffs und der Schild, der die Drachenseele schützt, wird gestört, womit das Ende allen Lebens auf Azeroth eingeleitet wird." }
entries[106372] = { ["name"] = "Instabile Monstrosität", ["text"] = "Sofort\nDie ansteigende Zwielichtinstabilität lässt alle 6 Sek. Zwielichtenergien aus Ultraxions Körper ausbrechen. Die Instabilität verhindert, dass Ultraxion Angriffe parieren kann." }
